mapper.select:
SELECT COUNT(1) AS totalCount
FROM moral_activity
WHERE deleted = 0

    AND create_time >= #{startTime}


    AND create_time  <=  #{endTime}

SELECT status AS status, COUNT(1) AS totalCount
FROM moral_activity
WHERE deleted = 0

    AND create_time >= #{startTime}


    AND create_time  <=  #{endTime}

GROUP BY status

SELECT activity_type AS activityType, COUNT(1) AS totalCount
FROM moral_activity
WHERE deleted = 0

    AND create_time >= #{startTime}


    AND create_time  <=  #{endTime}


    AND activity_type = #{activityType}

GROUP BY activity_type

SELECT DATE_FORMAT(create_time, '%Y-%m') AS date, COUNT(1) AS totalCount FROM moral_activity WHERE deleted = 0
AND create_time >= #{startTime}
AND create_time <= #{endTime}
GROUP BY date ORDER BY date ASC

SELECT DATE_FORMAT(start_time, '%Y-%m') AS date, COUNT(1) AS totalCount FROM moral_activity WHERE deleted = 0
AND start_time >= #{startTime}
AND start_time <= #{endTime}
GROUP BY date ORDER BY date ASC

SELECT COUNT(1) as totalCount
FROM moral_activity
WHERE deleted = 0

    AND start_time >= #{startTime}


    AND start_time  <=  #{endTime}


    AND activity_type = #{activityType}
